// Generates packages/api/src/generated/schema.js from packages/api/openapi.json.
// Usage (from the repo root): node scripts/gen-schema.mjs [--check]
import { readFileSync, writeFileSync } from 'node:fs';

const SRC = 'packages/api/openapi.json';
const DEST = 'packages/api/src/generated/schema.js';

const spec = JSON.parse(readFileSync(SRC, 'utf8'));
const schemas = spec.components.schemas;

const out = [
  '// DO NOT EDIT. Generated by scripts/gen-schema.mjs from packages/api/openapi.json.',
  '// Change openapi.json and run `npm run gen`.',
  '',
  `export const schemas = ${JSON.stringify(schemas, null, 2)};`,
  '',
].join('\n');

if (process.argv.includes('--check')) {
  const current = readFileSync(DEST, 'utf8');
  if (current !== out) {
    console.error(`${DEST} is out of date. Run \`npm run gen\`.`);
    process.exit(1);
  }
} else {
  writeFileSync(DEST, out);
}
